('0ce93715-f9b1-5e81-88f7-4b6a8e523078'::uuid,'est','"Solid Geometry & Volume"'::jsonb,'medium','mcq','"[Figure: Soccer field 100 yd long plus 18 yd end zones on each side; width 60.5 yd.]\nA city has decided to store an estimated 15,000 cubic yards of sand for later distribution to the city''s beaches. If this sand were spread evenly over the entire soccer field shown, about how many yards deep would the sand be?"'::jsonb,'[{"key":"A","text":"Less than 1"},{"key":"B","text":"Between 1 and 2"},{"key":"C","text":"Between 2 and 3"},{"key":"D","text":"Between 3 and 4"},{"key":"E","text":"More than 4"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t10.md","source_sha256":"f20516078371096927f6322b82ff1576ab3861b0fb64e776ba5ff7fbc66dbac0","source_question_id":"T10-04","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Solid Geometry & Volume"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from book_t10.md (T10-04)."'::jsonb),
