('1a98e65e-44d9-5f09-a061-99ec4055bd69'::uuid,'est','"Solid Geometry & Volume"'::jsonb,'medium','mcq','"[Figure: Right triangular solid (prism) 4 feet thick; hypotenuse of the triangular base 15 feet, one leg 9 feet.]\nThe right triangular solid shown is 4 feet thick. The hypotenuse of the base measures 15 feet and one of the legs measures 9 feet. What is the volume of this solid, in cubic feet?"'::jsonb,'[{"key":"A","text":"108"},{"key":"B","text":"216"},{"key":"C","text":"270"},{"key":"D","text":"432"},{"key":"E","text":"540"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t10.md","source_sha256":"f20516078371096927f6322b82ff1576ab3861b0fb64e776ba5ff7fbc66dbac0","source_question_id":"T10-30","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Solid Geometry & Volume"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from book_t10.md (T10-30)."'::jsonb),
