('7063c42d-2528-5b40-96f2-c1511e13c2b0'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','numeric','"A cellular telephone company has two plans. Plan A charges $11 a month and $0.21 per minute. Plan B charges $20 a month and $0.10 per minute. After how much time, to the nearest minute, will the cost of plan A be equal to the cost of plan B?\n[A] 81 hr 48 min\n[B] 1 hr 36 min\n[C] 81 hr 8 min\n[D] 1 hr 22 min"'::jsonb,'[]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t10.md","source_sha256":"f20516078371096927f6322b82ff1576ab3861b0fb64e776ba5ff7fbc66dbac0","source_question_id":"T10-36","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from book_t10.md (T10-36)."'::jsonb),
('b21b785a-6d36-5f30-8598-a5cf9ecc3acb'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'medium','numeric','"The path of a rocket is represented by the equation y = √(25 − x²). The path of a missile designed to intersect the path of the rocket is represented by the equation x = (3/2)√y. The value of x at the point of intersection is 3. What is the corresponding value of y?\n[A] 2\n[B] 4\n[C] −4\n[D] −2"'::jsonb,'[]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t10.md","source_sha256":"f20516078371096927f6322b82ff1576ab3861b0fb64e776ba5ff7fbc66dbac0","source_question_id":"T10-37","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from book_t10.md (T10-37)."'::jsonb),
