('036be8d4-5562-5564-8817-cb21fd576d31'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','numeric','"Two numbers are in the ratio 2:5. If 6 is subtracted from their sum, the result is 50. What is the larger number?\n[A] 35\n[B] 55\n[C] 40\n[D] 45"'::jsonb,'[]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t10.md","source_sha256":"f20516078371096927f6322b82ff1576ab3861b0fb64e776ba5ff7fbc66dbac0","source_question_id":"T10-39","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from book_t10.md (T10-39)."'::jsonb),
('f371741f-ffa4-51f1-a5e1-1cbe030a81fe'::uuid,'est','"Triangles, Trigonometry & Similarity"'::jsonb,'medium','numeric','"If the roots of ax² + bx + c = 0 are real, rational, and equal, what is true about the graph of the function y = ax² + bx + c?\n[A] It lies entirely below the x-axis.\n[B] It is tangent to the x-axis.\n[C] It intersects the x-axis in two distinct points.\n[D] It lies entirely above the x-axis."'::jsonb,'[]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t10.md","source_sha256":"f20516078371096927f6322b82ff1576ab3861b0fb64e776ba5ff7fbc66dbac0","source_question_id":"T10-40","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from book_t10.md (T10-40)."'::jsonb),
